        if n == 1:
            return random.choice(['0', '1'])
        else:
            subformulas = [generate_boolean_formula(random.randint(1, n-1)) for _ in range(2)]
            operator = random.choice(['&', '|'])
            return f'({subformulas[0]} {operator} {subformulas[1]})'

    def evaluate_formula(formula):
        if formula == '0':
            return 0
        elif formula == '1':
            return 1
        else:
            left, operator, right = formula.split()
            if operator == '&':
                return evaluate_formula(left) & evaluate_formula(right)
            elif operator == '|':
                return evaluate_formula(left) | evaluate_formula(right)

    def concept_lattice(formula):
        variables = set()
        for char in formula:
            if char.isalpha():
                variables.add(char)

        n = len(variables)
        lattice = [[0] * (1 << n) for _ in range(1 << n)]

        for i in range(1 << n):
            for j in range(1 << n):
                if all((i & (1 << k)) == (j & (1 << k)) for k in variables):
                    lattice[i][j] = 1

        return lattice

    def frege_proof_width(formula):
        stack = []
        depth = 0
        max_depth = 0

        for char in formula:
            if char.isalpha():
                stack.append(char)
            elif char == '(':
                stack.append(char)
            elif char == ')':
                while stack[-1] != '(':
                    stack.pop()
                stack.pop()
                depth -= 1
            else:  # '&' or '|'
                stack.pop()
                depth += 1
                max_depth = max(max_depth, depth)

        return max_depth

    def min_formal_concepts(lattice):
        n = len(lattice)
        count = 0

        for i in range(1 << n):
            if all(lattice[i][j] == lattice[j][i] for j in range(1 << n)):
                count += 1

        return count

    def generate_random_formula(n):
        formula = generate_boolean_formula(n)
        while evaluate_formula(formula) == 0:
            formula = generate_boolean_formula(n)
        return formula

    instances_tested = 0
    total_concept_count = 0
    total_proof_width = 0

